WITH matched_keys AS (SELECT status, order_id FROM payments EXCEPT SELECT status, order_id FROM payments WHERE amount <= 520), reconciled AS (SELECT s.* FROM payments s INNER JOIN matched_keys k ON s.status = k.status AND s.order_id = k.order_id) SELECT DATE_TRUNC('WEEK', paid_at) AS week_start, CASE WHEN amount >= 1280 THEN 'HIGH' ELSE 'LOW' END AS amount_tier, (UNIX_TIMESTAMP(MAX(paid_at)) - UNIX_TIMESTAMP(MIN(paid_at))) / 60 AS duration_min, SUM(CASE WHEN status = 'REFUNDED' THEN amount ELSE 0 END) AS refunded_amount, PERCENTILE_APPROX(amount, 0.9) AS amount_p90, ROUND(AVG(amount), 2) AS avg_amount FROM reconciled GROUP BY DATE_TRUNC('WEEK', paid_at), CASE WHEN amount >= 1280 THEN 'HIGH' ELSE 'LOW' END HAVING PERCENTILE_APPROX(amount, 0.9) > 0;
